package com.wipro.hibernate;import org.hibernate.*;import java.util.*;public class Main{public static void main(String[]a){Scanner sc=new Scanner(System.in);System.out.print("Enter registration number: ");String id=sc.nextLine();try(Session s=HibernateUtil.getSessionFactory().openSession()){CarDetail c=s.createQuery("from CarDetail c where c.regNo=:reg",CarDetail.class).setParameter("reg",id).uniqueResult();if(c==null)System.out.println("Vehicle not found");else System.out.println(c.getRegNo()+" "+c.getModel()+" "+c.getColor()+" "+c.getManufacturer());}HibernateUtil.getSessionFactory().close();}}